    'fc.help_body' => 'Gere os códigos de atalho marcados a partir do telefone (como <code>*78</code>): Não incomodar (DND), reencaminhamento de chamadas, captura de chamadas de grupo/direcionada, escuta de chamadas, entrada/saída da fila (<code>*81&lt;queue id&gt;</code> / <code>*80&lt;queue id&gt;</code>), pausa / retoma na fila (<code>*22&lt;break id&gt;</code> / <code>*23</code>).',
