    'asterisk_settings.rtp_section_title' => 'Definições RTP (media)',
    'asterisk_settings.rtp_help_body' => 'Controla o intervalo de portas que transporta o áudio (RTP) e se o Asterisk rejeita áudio proveniente de uma origem inesperada. Este ficheiro (<code>/etc/asterisk/rtp.conf</code>) é agora gerado pelo painel; as edições manuais no servidor perdem-se no próximo "Aplicar".',
    'asterisk_settings.field_rtp_start' => 'Porta inicial RTP',
    'asterisk_settings.rtp_start_help' => 'Início do intervalo de portas reservado para os fluxos de áudio. Cada chamada simultânea consome portas deste intervalo.',
    'asterisk_settings.field_rtp_end' => 'Porta final RTP',
    'asterisk_settings.rtp_end_help' => 'Fim do intervalo. O coturn (relay TURN) utiliza 13479-14999 — uma sobreposição danifica o áudio WebRTC e é rejeitada ao guardar.',
    'asterisk_settings.field_rtp_strict' => 'RTP estrito (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Quando ativado, o Asterisk descarta silenciosamente o áudio proveniente de qualquer origem que não seja o endereço/porta remotos aprendidos (proteção contra ataques). Se o PBX remoto enviar media a partir de uma porta inesperada, isto provoca uma falha silenciosa de "sem áudio" sem qualquer rasto nos registos — pode ser desativado temporariamente para diagnóstico.',
    'asterisk_settings.rtp_strict_yes' => 'Ativado (recomendado)',
    'asterisk_settings.rtp_strict_no' => 'Desativado (para diagnóstico)',
    'asterisk_settings.rtp_restart_warning' => 'A definição de RTP estrito entra em vigor com "Aplicar". No entanto, uma alteração do INTERVALO DE PORTAS requer um reinício completo do Asterisk — o conjunto de portas é atribuído uma única vez quando o módulo é carregado.',
    'asterisk_settings.udptl_section_title' => 'Definições T.38 UDPTL (media de fax)',
    'asterisk_settings.udptl_help_body' => 'Define os intervalos de portas UDP e os parâmetros de correção de erros (FEC / checksum) para os pacotes de fax T.38 (UDPTL). Este ficheiro (<code>/etc/asterisk/udptl.conf</code>) é gerido dinamicamente.',
    'asterisk_settings.field_udptl_start' => 'Porta inicial UDPTL',
    'asterisk_settings.udptl_start_help' => 'Porta UDP inicial para os fluxos de fax T.38 (predefinida: 4100).',
    'asterisk_settings.field_udptl_end' => 'Porta final UDPTL',
    'asterisk_settings.udptl_end_help' => 'Porta UDP final para os fluxos de fax T.38 (predefinida: 4999).',
    'asterisk_settings.field_udptl_checksums' => 'Checksums UDPTL',
