    'asterisk_settings.field_udptl_fec_span' => 'Span FEC',
    'trunks.field_connection_mode' => 'Modo de ligação',
    'trunks.connection_mode_ip' => 'Baseado em IP (o par tem um IP estático)',
    'trunks.connection_mode_register' => 'Registo de entrada (o par regista-se em nós)',
    'trunks.connection_mode_help' => 'Baseado em IP: o par é identificado pelo seu endereço IP e o seu contacto é mantido estático — o modo recomendado para um par com IP fixo na mesma rede. Registo de entrada: o par envia-nos um SIP REGISTER e o seu endereço é aprendido a partir desse registo. Este modo requer um nome de utilizador e uma palavra-passe; o par autentica com eles tanto o registo como as chamadas.',
    'trunks.connection_mode_warning' => 'Mudar para o modo de registo remove o contacto estático: não podemos ligar para esse tronco ATÉ que o par se registe em nós. Efetue esta alteração em sincronia com a definição de registo do lado do par.',
