    'sound_packs.tab' => 'Pacotes de sons do Asterisk',
    'sound_packs.title' => 'Pacotes de sons oficiais do Asterisk',
    'sound_packs.help_title' => 'Pacotes de sons do Asterisk',
    'sound_packs.help_body' => 'Transfere e instala as mensagens de sistema e a música em espera oficiais do Asterisk a partir de <code>downloads.asterisk.org</code>. Cada pacote corresponde a um idioma num formato; o Asterisk reproduz o formato que corresponde ao codec da chamada e, caso contrário, transcodifica (g722 para G.722, ulaw/alaw para operadores).<br>- <strong>Core:</strong> mensagens de sistema, dígitos, correio de voz. <strong>Extra:</strong> mensagens adicionais; o pacote core do mesmo idioma tem de ser instalado primeiro.<br>- <strong>Música em espera (opsound):</strong> instalada em <code>/var/lib/asterisk/moh/opsound</code>; para a reproduzir, crie uma classe MOH chamada <strong>opsound</strong> no separador Música em espera.<br>- <strong>Türkçe (AiPBX):</strong> as mensagens em turco próprias do AiPBX (release no GitHub, verificada por SHA256); o idioma predefinido é o turco, pelo que removê-las silencia as mensagens do sistema. A remoção elimina apenas os ficheiros instalados pelo pacote.',
