    'ms_teams.guide_title' => 'Guia de integração Microsoft Teams',
    'ms_teams.guide_intro' => 'O AiPBX pode comunicar com o Microsoft Teams a dois níveis diferentes:',
    'ms_teams.guide_dr_title' => '1. Direct Routing (SBC / tronco SIP):',
    'ms_teams.guide_dr_desc' => 'Permite que os utilizadores do Teams efetuem e recebam chamadas internas e externas diretamente a partir do teclado do Teams no computador/telemóvel. Requer TLS (porta 5061), SRTP e um certificado SSL público válido (ex.: Let\'s Encrypt).',
    'ms_teams.guide_webhook_title' => '2. Webhooks e notificações de canal:',
    'ms_teams.guide_webhook_desc' => 'Envia Adaptive Cards interativos para canais do Teams designados relativamente a chamadas perdidas, correio de voz, faxes recebidos e alertas do call center. Não requer licenças de telefonia.',
    'ms_teams.guide_ps_title' => '3. Gerador automático de PowerShell:',
    'ms_teams.guide_ps_desc' => 'No separador "Guia PowerShell", gere automaticamente, com um clique, comandos PowerShell personalizados de acordo com as definições do seu PBX, para executar na consola de administrador do Microsoft 365.',
