    'certificates.header_title' => 'Certificado TLS',
    'certificates.help_title' => 'Guia de certificados',
    'certificates.help_body' => 'O portal (HTTPS), o WebRTC TURNS e o SIP-TLS/WSS partilham um único certificado; as alterações efetuadas aqui são aplicadas em conjunto ao Apache, ao coturn e ao Asterisk. O <b>Let\'s Encrypt</b> é gratuito e renova-se automaticamente; o domínio deve apontar para este servidor e a porta 80 deve estar acessível a partir da Internet. Se a sua organização tiver um certificado, <b>carregue-o</b> (PEM ou PFX); os certificados carregados não são renovados automaticamente, pelo que deve carregar um novo antes de expirar. Com um certificado <b>autoassinado</b>, os navegadores mostram um aviso e o TURNS não funciona nos navegadores: as chamadas WebRTC atrás de firewalls podem ficar sem áudio.',
