    'sidebar.item_queue_reports' => 'Centro de relatórios de filas',
    'queue_reports.title' => 'Centro de relatórios de filas',
    'queue_reports.help_title' => 'Guia dos relatórios de filas',
    'queue_reports.help_body' => 'Cada chamada que entra numa fila é contada uma vez. <b>Atendida</b>: ligada a um agente. <b>Perdida</b>: o autor da chamada desligou enquanto aguardava ou o tempo da fila esgotou. <b>Abandono curto</b>: desligou em menos de %d segundos; excluída do nível de serviço. <b>Nível de serviço</b>: chamadas atendidas dentro do objetivo, sobre todas as chamadas exceto os abandonos curtos. <b>ASA</b>: tempo médio de espera das chamadas atendidas. <b>AHT</b>: tempo médio de conversação. <b>Taxa de atendimento</b> (agente): com que frequência o agente atendeu quando a fila o chamou. <b>Devolução de chamada</b>: uma chamada perdida conta como resolvida quando o seu número foi posteriormente chamado a partir de uma extensão, ou voltou a ligar e foi atendido. Os dados provêm do registo de filas do Asterisk; o relatório pode ser transferido em PDF ou Excel.',
