    'ai_tts.help_title' => 'Guia do TTS na nuvem',
    'ai_tts.help_body' => 'Converte texto em voz natural com serviços na nuvem (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Ouça o resultado, transfira-o em MP3 ou guarde-o como <b>anúncio</b> com um clique: é convertido para o formato do Asterisk (WAV 8 kHz) e adicionado a Sons &amp; Anúncios para IVR, rotas de entrada e condições horárias (entra em vigor após Aplicar). <b>Estes serviços são pagos</b> e cobram por carácter; cada síntese fica guardada no histórico com o respetivo número de caracteres. As chaves de acesso obtêm-se na consola de cada fornecedor, são guardadas encriptadas e nunca voltam a ser mostradas na página.',
