    'push.help_intro' => 'O softphone móvel AI PBX tem uma <strong>arquitetura de notificações em camadas</strong>:',
    'push.help_layer0' => '<strong>Camada 0 (sem dependências - predefinição):</strong> uma ligação WSS persistente, um serviço em primeiro plano <code>specialUse</code> compatível com Android 15 e um watchdog <code>AlarmManager</code> resistente ao Doze que o reativa. Não é necessário nenhum serviço externo; as chamadas chegam mesmo com o dispositivo inativo ou o ecrã desligado.',
    'push.help_layer1' => '<strong>Camada 1 (opcional - Google FCM):</strong> uma garantia adicional de ativação em dispositivos de fabricantes com restrições agressivas de bateria (Xiaomi, Huawei...) ou quando o utilizador fechou a aplicação. <em>Só é acionada quando a extensão não tem um registo SIP ativo, pelo que as extensões registadas não sentem qualquer atraso.</em>',
    'push.help_no_fcm' => 'Se não pretender utilizar o FCM, deixe o fornecedor como <strong>"Local (sem dependências)"</strong>. A aplicação móvel não estabelece então qualquer contacto de rede com a Google.',
