    'mailtpl.invite_new.subject' => '[{brand}] A sua conta foi criada - defina a sua palavra-passe',
    'mailtpl.invite_new.body' => '<p>Olá {name},</p>{mobile_section}<p>A sua conta na central <strong>{brand}</strong> está pronta. Para iniciar sessão, defina a sua palavra-passe com o botão abaixo.</p>{account_details}{reset_button}<p>Se o botão não funcionar, abra esta ligação: {reset_link}</p><p><em>A ligação da palavra-passe é válida durante 48 horas e funciona uma única vez. Se não esperava este e-mail, contacte o seu administrador de sistema.</em></p>',
