    'mailtpl.invite.body' => '<p>Olá {name},</p>{mobile_section}<p>Aqui tem uma nova ligação para definir a sua palavra-passe em <strong>{brand}</strong>.</p>{account_details}{reset_button}<p>Se o botão não funcionar, abra esta ligação: {reset_link}</p><p><em>A ligação da palavra-passe é válida durante 48 horas e funciona uma única vez. Se não a pediu, contacte o seu administrador de sistema.</em></p>',
    'mailtpl.password_reset.subject' => '[{brand}] Reponha a sua palavra-passe',
    'mailtpl.password_reset.body' => '<p>Olá {name},</p><p>Foi pedida a reposição da palavra-passe da sua conta <strong>{username}</strong>.</p>{reset_button}<p>Se o botão não funcionar, abra esta ligação: {reset_link}</p><p><em>A ligação é válida durante 30 minutos. Se não a pediu, ignore este e-mail; a sua palavra-passe mantém-se.</em></p>',
    'mailtpl.voicemail.subject' => 'Nova mensagem de voz de {caller} ({duration})',
