    'mailtpl.fax_received.body' => '<p>Foi recebido um novo fax.</p><ul><li><strong>Unidade:</strong> {department}</li><li><strong>Número de fax:</strong> {did}</li><li><strong>De:</strong> {caller}</li><li><strong>Páginas:</strong> {pages}</li><li><strong>Recebido:</strong> {date}</li></ul><p>O fax é anexado em PDF quando essa opção está ativa. Todos os faxes estão na caixa de entrada de fax: {portal_link}</p>',
