    'storage.help_title' => 'Onde ficam os ficheiros do chat',
    'storage.help_body' => '<p>Os anexos do chat, as suas miniaturas e as imagens de grupo são guardados por predefinição no disco do servidor (<code>/var/lib/aipbx/chat_files</code>). Com um armazenamento compatível com S3 (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) vão para um bucket e os ficheiros grandes ficam fora do PBX.</p><p>As transferências continuam a passar pelo serviço de chat, pelo que só os participantes de um chat podem abrir os seus ficheiros; o bucket pode continuar privado. Os ficheiros guardados antes da mudança continuam a ser servidos a partir do disco até os mover. As definições do bucket são verificadas antes de serem guardadas.</p><p>As gravações de chamadas, o correio de voz e os faxes ficam no disco local.</p>',
