    'netsvc.help_title' => 'Serviços de rede',
    'netsvc.help_body' => 'Os telefones de secretária encontram sozinhos o servidor de aprovisionamento quando o servidor DHCP distribui o seu endereço (opção 66). DHCP e TFTP são ativados separadamente. Com o <strong>Servidor DHCP</strong> desativado, mantém-se o seu próprio servidor DHCP: defina nele as opções indicadas abaixo. Com ele ativado, o AiPBX distribui endereços numa interface ou VLAN. O <strong>Servidor TFTP</strong> serve os ficheiros de arranque e o firmware que carregar. A configuração de cada telefone (com a palavra-passe SIP) é sempre servida por HTTPS, nunca por TFTP.',
