    'web_widgets.help_title' => 'Widget de chamada para o site e formulário de retorno de chamada',
    'web_widgets.help_body' => 'Um widget coloca um botão «Ligue-nos» em qualquer site. Os visitantes falam consigo a partir do navegador por WebRTC, ou deixam o número e o PBX liga-lhes. Cole o código de uma linha no site (ou no plugin WordPress) e prima <strong>Aplicar</strong> depois de guardar.',
    'web_widgets.help_number' => 'Número:',
    'web_widgets.help_number_desc' => 'Um widget entra no PBX como um tronco. O seu número é o DID destas chamadas nos relatórios e no CDR; o visitante nunca escolhe para onde vai a chamada.',
    'web_widgets.help_security' => 'Segurança:',
    'web_widgets.help_security_desc' => 'Só os sites permitidos podem usar o widget. Cada chamada precisa de um token de utilização única, e os limites (por IP, por dia, chamadas simultâneas, duração da chamada) aplicam-se a cada pedido. Cada pedido é registado abaixo.',
    'web_widgets.help_callback' => 'Retorno de chamada:',
    'web_widgets.help_callback_desc' => 'O PBX liga ao visitante pela rota de saída escolhida e, quando ele atende, encaminha-o para o destino. Só são marcados números que começam pelos prefixos permitidos, e é obrigatório um limite diário.',
    'web_widgets.help_wordpress' => 'WordPress:',
